-- Owner/Oportunidades homologation hardening.
-- Expired opportunities and maintenance-service objects must not surface as actionable Radar matches.
insert into public.client_capability_match_terms(client_id,capability_id,term,term_kind,active)
select c.client_id,c.id,x.term,'exclude',true from public.client_capabilities c cross join(values('prestação de serviços de manutenção'),('serviços de manutenção preventiva'),('serviço de manutenção preventiva'),('serviços de manutenção corretiva'),('serviço de manutenção corretiva'),('mão de obra especializada'))x(term) where c.selected=true
on conflict(client_id,capability_id,term,term_kind) do update set active=true;
update public.client_opportunity_matches m set match_status='filtered_out',participation_allowed=false,updated_at=now() from public.public_opportunities o where o.id=m.opportunity_id and m.match_status<>'filtered_out' and (o.proposal_deadline is not null and o.proposal_deadline<now() or lower(coalesce(o.title,'')||' '||coalesce(o.object_text,'')) like any(array['%prestação de serviços de manutenção%','%serviços de manutenção preventiva%','%serviço de manutenção preventiva%','%serviços de manutenção corretiva%','%serviço de manutenção corretiva%','%mão de obra especializada%']));
create or replace view public.client_radar_dashboard with(security_invoker=true) as
select distinct on(m.client_id,m.capability_id,coalesce(o.canonical_key,'SOURCE:'||o.source_id::text||':'||o.source_external_id)) m.client_id,m.capability_id,o.id opportunity_id,o.process_number,o.title,o.object_text,o.buyer_name,o.city,o.state,o.modality,o.publication_date,o.proposal_deadline,o.estimated_value,o.currency,o.source_url,public.opportunity_lifecycle(o.proposal_deadline,now()) lifecycle,m.match_status,m.deterministic_score,m.participation_allowed,m.method_version,m.updated_at match_updated_at from public.client_opportunity_matches m join public.public_opportunities o on o.id=m.opportunity_id where m.match_status<>'filtered_out' order by m.client_id,m.capability_id,coalesce(o.canonical_key,'SOURCE:'||o.source_id::text||':'||o.source_external_id),case when exists(select 1 from public.radar_sources s where s.id=o.source_id and s.code='pncp') then 0 when exists(select 1 from public.radar_sources s where s.id=o.source_id and s.code='compras_gov_br') then 1 else 2 end,m.updated_at desc;